#!/usr/bin/env python3
"""Rebuild Russian configurator help/defaults against the accepted physics schema.

Defaults are estimates sampled from the committed examples, not measurements.
"""
import json
from pathlib import Path
r=Path(__file__).resolve().parents[1]
schema=json.loads((r/'Assets/DronePhysics/Resources/DronePhysics/drone-profile.schema.json').read_text());defs=schema['$defs']
text='''schemaVersion|Версия схемы||Версия согласованного контракта физики. Её меняют только вместе с поддержкой новой схемы в движке.
metadata|Описание аппарата||Название и описание модели; не меняют физические силы.
name|Название||Имя дрона в галерее и отчётах.
manufacturer|Производитель||Производитель реального аппарата или автор учебной модели.
model|Модель||Выбор способа расчёта или название аппарата в его описании. Связанные параметры должны соответствовать выбранному способу расчёта.
description|Описание||Область применения, источник характеристик и ограничения профиля.
coordinateSystem|Система координат||Все физические точки выражены относительно корня дрона: X вправо, Y вверх, Z вперёд. Один метр в профиле равен одному метру мира.
convention|Направление осей||Физика использует систему Unity: X вправо, Y вверх, Z вперёд. Ориентация импортированной картинки модели настраивается отдельно.
lengthUnit|Единица длины||Все длины физического профиля хранятся в метрах.
modelScaleMetersPerUnit|Масштаб модели|м/ед.|Метров на исходную единицу модели. Меняет размер визуальной геометрии; масса, точки роторов и инерция задаются отдельно в SI.
physicsConfiguration|Модели физики||Включение физических эффектов и выбор уровня детализации расчёта.
fidelity|Детализация физики||Базовая или расширенная конфигурация расчёта. Это отдельный параметр от сложности интерфейса.
modules|Физические модули||Каждый переключатель управляет конкретным эффектом и может требовать дополнительных исходных данных.
motorResponse|Отклик двигателя||Учитывает запаздывание изменения RPM. Для инерционного привода нужны его электрические параметры.
bodyDrag|Сопротивление корпуса||Добавляет аэродинамическое сопротивление корпуса по заданным коэффициентам и площадям.
windInteraction|Воздействие ветра||Использует скорость относительно воздуха в точках приложения сил. Без включённого сопротивления или аэродинамики ветер сам по себе не создаёт силу.
groundEffect|Экранный эффект||Эмпирически увеличивает положительную тягу вблизи земли. Требует параметров экрана; не добавляет вторую независимую силу.
rotorAerodynamics|Аэродинамика роторов||Учитывает сопротивление роторов поперечному потоку и заданную эмпирическую поправку подъёмной силы.
bladeFlapping|Маховое движение лопастей||Добавляет ограниченный эмпирический момент от бокового воздушного потока. Требует коэффициента и пределов применения.
inducedDrag|Осевой поток||Добавляет ограниченную эмпирическую поправку тяги от осевого потока. Нельзя накладывать на карту RPM/J, уже учитывающую этот эффект.
batteryDischarge|Разряд батареи||Интегрирует потреблённый ток и уменьшает SOC. Требует модели батареи и ёмкости.
batteryVoltageSag|Просадка напряжения||Учитывает падение напряжения I·R под нагрузкой. Требует электрической модели питания.
motorElectrical|Электрический привод||Связывает напряжение, ток, момент мотора и ограничения ESC. Требует модели Electrical и данных каждого мотора.
gyroscopicRotorEffects|Гироскопический момент||Добавляет момент от вращающихся роторов при изменении ориентации рамы. Требует момента инерции ротора и совместимого режима привода.
massProperties|Масса и инерция||Определяют линейное и угловое ускорение дрона от заданных сил и моментов.
massKg|Общая масса|кг|Полная масса аппарата с батареей, двигателями и нагрузкой. Не прибавляйте массу двигателей второй раз.
centerOfMassLocalM|Центр масс|м|Точка COM относительно корня дрона. Расстояние от неё до ротора определяет плечо силы и момент.
dimensionsM|Габариты X / Y / Z|м|Физические размеры оболочки. Используются для приближённой инерции и геометрии. Все три компоненты должны быть положительными.
inertia|Момент инерции||Определяет, какое угловое ускорение создаёт момент силы вокруг каждой оси: чем больше инерция, тем труднее раскрутить аппарат. AutoBox предполагает однородное прямоугольное тело с заданной общей массой m и размерами dx/dy/dz: Ix=m(dy²+dz²)/12, Iy=m(dx²+dz²)/12, Iz=m(dx²+dy²)/12; главные оси совпадают с X/Y/Z. Это не расчёт по силуэтам mesh и не учитывает отдельные массы батареи, моторов и нагрузки. При смещённом COM остаётся приближением. ManualPrincipal использует главные моменты относительно центра масс из измерений или CAD и ориентацию этих осей.
mode|Способ расчёта||Выбор представления данных. Необходимые поля зависят от выбранной ветви модели.
principalMomentsKgM2|Главные моменты инерции|кг·м²|Положительные Ix, Iy, Iz. Должны удовлетворять неравенствам треугольника: один момент не превышает сумму двух остальных.
principalAxesRotationXyzw|Ориентация главных осей|кватернион XYZW|Поворот главных осей инерции относительно осей корня дрона, записанный как кватернион X/Y/Z/W (не углы Эйлера). [0,0,0,1] означает совпадение осей. Для физического поворота сумма квадратов компонент должна быть 1. Нормализация делит все четыре компоненты на их общую длину и приводит представление к единичному кватерниону. Нулевой кватернион не задаёт поворот.
rotors|Роторы||Независимые точки приложения тяги. Число роторов допускается физикой; текущий пилот поддерживает четыре совместимых ротора с осями +Y.
rotorId|Имя ротора||Уникальный идентификатор, связывающий геометрию, телеметрию и визуальный узел.
geometry|Геометрия ротора||Физическая точка ротора, направление его тяги и направление вращения.
positionLocalM|Положение|м|Координаты точки относительно корня дрона. Для ротора — центр приложения тяги; для поверхности — точка аэродинамического сопротивления.
thrustAxisLocal|Ось тяги||Единичный ненулевой вектор тяги в локальных осях дрона. Не зависит от поворота визуального винта. Кнопка нормализации сохраняет направление.
spinDirection|Направление вращения||CW/CCW: вид вдоль направления −оси тяги, со стороны её положительного конца. Меняет знак реактивного момента рамы.
motor|Двигатель||Пределы оборотов, динамика привода и электрические характеристики конкретного ротора.
minRpm|Минимальные обороты|об/мин|Нижний предел работающего привода. Требуется min ≤ idle < max. Для таблиц текущий пилот требует min=0.
idleRpm|Обороты холостого режима|об/мин|Минимальный режим вооружённого привода; ниже максимальных оборотов.
maxRpm|Максимальные обороты|об/мин|Верхний предел оборотов. Таблица характеристик должна покрывать используемый диапазон.
responseTimeUpS|Разгон|с|Постоянная времени первого порядка при росте команды: за одну постоянную достигается около 63% изменения RPM. Это не время полного разгона.
responseTimeDownS|Замедление|с|Постоянная времени первого порядка при снижении команды оборотов. Может отличаться от разгона.
rotatingInertiaKgM2|Инерция вращающейся части|кг·м²|Момент инерции ротора мотора и винта относительно оси вращения; должен быть положительным в RotorInertia.
dynamicsModel|Динамика мотора||FirstOrder задаёт запаздывание оборотов. RotorInertia рассчитывает разгон из баланса моментов и требует Electrical батарею.
electrical|Электрические параметры||Упрощённая DC/BLDC-модель. Коммутация, PWM и индуктивность обмоток не моделируются.
motorKvRpmPerVolt|KV мотора|об/мин/В|Скоростная постоянная. Через Kt=60/(2πKV) связывает ток и момент. Сам по себе KV не задаёт тягу винта.
motorResistanceOhm|Сопротивление мотора|Ом|Эквивалентное сопротивление привода. Определяет просадку и тепловые потери I²R.
noLoadCurrentA|Ток холостого хода|А|Оценка потерь мотора при вращении без полезной нагрузки винта.
maxCurrentA|Предел тока мотора|А|Ограничение моторного тока. При его достижении привод теряет доступный момент.
maxPowerW|Предел мощности мотора|Вт|Дополнительное ограничение доступной механической/электрической мощности в принятой модели привода.
motorEfficiency|КПД мотора||Доля полезной мощности: больше 0 и не больше 1. Потери переходят в тепло, когда включена тепловая модель.
efficiencyCurve|Кривая КПД||КПД как функция доли нагрузки 0…1. Строки должны быть согласованы и покрывать требуемый диапазон.
loadFraction|Доля нагрузки||Безразмерная относительная нагрузка 0…1 для таблицы КПД.
efficiency|КПД||Доля полезной мощности, больше 0 и не больше 1.
escEfficiency|КПД ESC||Доля мощности, переданная регулятором двигателю; потери нагревают ESC.
escMaxCurrentA|Предел тока ESC|А|Ток, который регулятор может передать мотору в этой упрощённой модели.
thermal|Тепловая модель||Сосредоточенная теплоёмкость и охлаждение компонента. Требуется при включённом thermalEnabled.
escThermal|Нагрев ESC||Отдельные теплоёмкость, охлаждение и температурные пороги регулятора.
resistanceReferenceTemperatureK|Температура отсчёта R|К|Температура, при которой измерено сопротивление обмотки.
resistanceTemperatureCoefficientPerK|Температурный коэффициент R|1/К|В модели R(T)=Rref·(1+α·(T−Tref)). Работает при включённой тепловой модели.
heatCapacityJPerK|Теплоёмкость|Дж/К|Энергия, необходимая для нагрева компонента на 1 К. Больше значение — медленнее нагрев.
heatTransferWPerK|Охлаждение без потока|Вт/К|Мощность отвода тепла на каждый градус разницы с воздухом.
airflowHeatTransferWPerKPerMps|Охлаждение потоком|Вт/(К·м/с)|Дополнительная теплопередача при росте скорости воздуха; линейная оценка до заданного предела скорости.
maxAirSpeedMps|Предел скорости воздуха|м/с|Верхняя скорость применения выбранной эмпирической модели. Это её область применимости, не максимальная скорость дрона.
initialTemperatureK|Начальная температура|К|Температура компонента в начале симуляции, абсолютная шкала Кельвина.
derateStartTemperatureK|Начало снижения мощности|К|Порог, выше которого доступная мощность плавно ограничивается. Должен быть ниже температуры отключения.
cutoffTemperatureK|Температура отключения|К|Порог полного термического ограничения компонента. После охлаждения поведение определяет текущая модель.
propeller|Винт||Размеры и число лопастей. Тягу задаёт выбранная модель характеристик, а не только диаметр/шаг.
diameterM|Диаметр винта|м|Диаметр диска ротора. Участвует в Ct/Cq, площади диска и экранном эффекте.
pitchM|Шаг винта|м|Геометрический шаг. Хранится в профиле, но не заменяет измеренные коэффициенты тяги.
bladeCount|Число лопастей||Положительное целое число; описание винта, не самостоятельный коэффициент тяги.
performance|Характеристики винта||Выберите Ω², RPM-таблицу, Ct/Cq или карту RPM/J по доступным измерениям.
kThrustNPerRadPerSecSquared|Коэффициент тяги kT|Н/(рад/с)²|T=kT·ω². Обороты преобразуются из RPM в рад/с. Измеренный kT относится к заданной плотности воздуха.
kTorqueNmPerRadPerSecSquared|Коэффициент момента kQ|Н·м/(рад/с)²|Q=kQ·ω². Знак реакции рамы отдельно задаётся CW/CCW; здесь величина неотрицательна.
referenceAirDensityKgM3|Плотность измерения|кг/м³|Плотность воздуха при измерении тяги/момента или калибровке коэффициентов. Это условие исходных данных винта, а не плотность текущего окружения: воздух симуляции задаётся отдельно. Ω² и RPM-таблицы не масштабируются автоматически на другую плотность; несовместимые условия отклоняются. Ct/Cq и карта RPM/J используют плотность воздуха симуляции.
ct|Коэффициент тяги Ct||Для Ct/Cq: T=Ct·ρ·n²·D⁴, n в оборотах/с. В карте RPM/J Ct может иметь отрицательную ветвь.
cq|Коэффициент момента Cq||Q=Cq·ρ·n²·D⁵. Если источник публикует Cp, используйте Cq=Cp/(2π).
rpmTable|RPM-таблица||Измеренные RPM, тяга, момент и необязательный ток. Нужны разные возрастающие RPM и покрытие диапазона мотора; значения на графике берутся из этих строк.
rpm|Обороты|об/мин|Частота вращения винта. RPM/60 даёт обороты/с; RPM·2π/60 — рад/с.
thrustN|Тяга|Н|Измеренная сила одного ротора. 1 кгс ≈ 9,81 Н; не вводите килограммы вместо ньютонов.
torqueNm|Момент винта|Н·м|Измеренный аэродинамический момент одного винта. Не смешивайте с плечевым моментом тяги.
currentA|Измеренный ток|А|Необязательный измеренный ток одного привода. Если известен только ток всего стенда, не выдавайте его за ток одного мотора.
performanceMap|Карта RPM / J||Полная прямоугольная сетка RPM × J. Должна включать J=0 и минимум два J; отсутствующие ячейки не интерполируются как нули.
advanceRatio|Коэффициент поступи J||J=Vaxial/(nD). Положительный осевой поток соответствует движению ротора вдоль оси тяги относительно воздуха.
reynolds|Число Рейнольдса||Необязательные метаданные измерения карты. Не используется как независимая ось интерполяции текущего runtime.
outOfRangePolicy|За пределами измерений||Reject запрещает выход за таблицу. Clamp использует граничный коэффициент/значение; не доказывает точность за измеренным диапазоном.
advancedAerodynamics|Расширенная аэродинамика||Эмпирические поправки ротора. Коэффициенты требуют отдельной калибровки; пределы ограничивают величину эффекта.
rotorDragCoefficientKgPerRad|Сопротивление ротора|кг/рад|F=−K·ω·Vperp. В эту модель не добавляйте ещё один множитель плотности.
bladeFlappingCoefficient|Коэффициент махового момента|кг·м/рад|M=−K·ω·(Vair×axis), с ограничением по моменту. Это приближённый эффект, не расчёт деформации лопасти.
inducedDragCoefficient|Поправка осевого потока|кг/рад|Вносит −K·ω·Vaxial в тягу. Используется только с совместимой статической базовой моделью.
translationalLiftCoefficientKgPerM|Поправка поступательной тяги|кг/м|Добавляет K·|Vperp|² с заданным ограничением относительно базовой положительной тяги.
maxThrustCorrectionFraction|Предел поправки тяги||Максимальная абсолютная эмпирическая поправка как доля базовой положительной тяги, 0…0,5.
maxFlappingMomentRatio|Предел махового момента||Ограничивает момент относительно T·D/2. Не заменяет калибровку коэффициента.
operatingEnvelope|Область применения||Задаёт предельные скорости осевого подъёма, спуска и бокового потока для проверки области достоверности модели винта. Превышение сообщает диагностика: движение не ограничивается, дополнительные силы VRS, wake или dynamic inflow не рассчитываются. ReportOnly — единственный режим, выбираемый автоматически.
maxAxialClimbSpeedMps|Предел осевого набора|м/с|Диагностический предел положительной скорости вдоль оси тяги.
maxAxialDescentSpeedMps|Предел осевого снижения|м/с|Диагностический предел скорости против оси тяги; не включает физическую модель вихревого кольца.
maxLateralSpeedMps|Предел боковой скорости|м/с|Диагностическая граница поперечного потока для профиля ротора.
bodyAerodynamics|Аэродинамика корпуса||Выберите сопротивление по осям, по проекции или по отдельным поверхностям. Независимые модели не суммируются как одна и та же сила.
dragCd|Коэффициенты Cd X / Y / Z||Неотрицательные коэффициенты сопротивления по осям корпуса. Калибруются независимо от площади.
referenceAreaM2|Площади X / Y / Z|м²|Площади поперечной проекции по осям. Для коробки Ax=Y·Z, Ay=X·Z, Az=X·Y.
dragCoefficient|Коэффициент сопротивления Cd||Неотрицательный эмпирический коэффициент сопротивления поверхности или проекции.
projectedArea|Проекция корпуса||Площадь силуэта неподвижного корпуса по направлениям потока. При специальном экспорте профиля в Unity (DroneLab → Geometry → Export Profile with Mesh Silhouette) выбранное поддерево Body Mesh Root растеризуется заново: 13 осей, эквивалентных 26 направлениям, поскольку A(d)=A(−d). Silhouette Resolution задаёт число пикселей по большей стороне проекции: 16–512, по умолчанию 128; это точность площади, а не число ракурсов. В этом runtime-конфигураторе импорт GLB/glTF, сохранение или экспорт пакета не запускают этот расчёт: используется сохранённая таблица. После изменения формы, масштаба или поворота корпуса таблицу нужно пересчитать. Больше направлений можно подготовить отдельно и задать в таблице. Винты в выбранную геометрию корпуса включать не следует; Cd задаётся отдельно и из mesh не определяется.
samples|Таблица проекций||Направление и положительная площадь силуэта. Направления должны быть единичными, без дубликатов; учитывается симметрия противоположных направлений.
directionLocal|Направление проекции||Единичный вектор направления потока в локальных осях дрона.
areaM2|Площадь|м²|Площадь проекции или аэродинамического участка. Не должна быть нулевой.
dragApplicationPointLocalM|Точка сопротивления|м|Точка приложения результирующей силы относительно корня. Её смещение от COM создаёт аэродинамический момент.
surfaces|Аэродинамические поверхности||Отдельные двусторонние участки давления с площадью, нормалью и плечом силы. Не полноценная модель крыла.
surfaceId|Имя поверхности||Уникальный идентификатор аэродинамического участка.
normalLocal|Нормаль поверхности||Единичный вектор нормали участка. Направление определяет нормальную составляющую потока.
coefficient|Коэффициент экрана||Неотрицательный коэффициент эмпирического усиления тяги возле поверхности.
minHeightRadiusRatio|Минимальная высота / радиус||Нижний предел отношения h/R в формуле экрана. Устраняет сингулярность при касании земли.
maxMultiplier|Максимальное усиление||Максимальный множитель положительной тяги у земли. Не меньше 1.
powerSystem|Питание и нагрев||Модель батареи, ограничения мощности и включение теплового расчёта.
battery|Батарея||None выключает модель питания; Simple использует упрощённый расход; Electrical связывает батарею и электрический привод.
cellCount|Число ячеек||Число последовательно соединённых ячеек; напряжения OCV задаются для всего пакета, не одной ячейки.
nominalVoltageV|Номинальное напряжение|В|Номинальное напряжение всего пакета. Не путайте с OCV при полном заряде.
capacityAh|Ёмкость|А·ч|Ёмкость батареи в ампер-часах: 1300 мА·ч = 1,3 А·ч. Участвует в интегрировании SOC.
initialSoc|Начальный заряд SOC||Доля заряда 0…1: 1 соответствует 100%. Это начальное состояние, а не текущая телеметрия.
internalResistanceOhm|Внутреннее сопротивление|Ом|Эквивалентное сопротивление всего пакета. Просадка ΔV=I·R; потери I²R нагревают батарею.
maxDischargeCurrentA|Предел тока батареи|А|Максимальный ток всего пакета; ограничивает суммарную мощность всех приводов.
ocvCurve|Кривая OCV||Напряжение без нагрузки всего пакета в зависимости от SOC. Нужны точки SOC=0 и SOC=1 и согласованные возрастающие значения.
soc|Заряд SOC||Доля заряда 0…1; в таблице 0,5 означает 50%.
voltageV|Напряжение без нагрузки|В|OCV пакета при данной доле заряда, до просадки под током.
thermalEnabled|Тепловой расчёт||Включает нагрев батареи, моторов и ESC, охлаждение и термическое снижение мощности. Требует всех совместимых тепловых данных.
derived|Производные характеристики||Результаты расчёта. Редактирование этих сохранённых метаданных не изменяет уравнения движения; текущие результаты проверки показываются отдельно.
projectedAreaLut|Производная таблица площади||Подготовленные метаданные площади; активная модель проекции задаётся в bodyAerodynamics.
hoverRpm|Оценка оборотов зависания|об/мин|Сохранённая справочная оценка. Реальное зависание зависит от баланса сил, питания и геометрии.
maxTotalThrustN|Оценка общей тяги|Н|Сохранённые метаданные суммарной тяги. Проверка профиля рассчитывает текущую оценку независимо.
thrustToWeightRatio|Оценка тяга / вес||Сохранённые метаданные. Отношение >1 — необходимое, но недостаточное условие управляемого зависания.
rotorDiskAreasM2|Площади дисков роторов|м²|Справочные площади πD²/4 по роторам. Не являются второй моделью тяги.
approximateInertiaKgM2|Приближённая инерция|кг·м²|Справочная оценка Ix/Iy/Iz. Рабочая инерция задаётся в massProperties.
parameterProvenance|Источники параметров||Происхождение данных и уверенность: измерение, производитель, вычисление или оценка. Позволяет отличать калибровку от демонстрационных значений.
path|Поле профиля||Путь к параметру или группе, для которой указан источник.
sourceType|Тип источника||Измеренные, опубликованные, вычисленные и оценочные параметры имеют разную степень подтверждения.
source|Источник||Название измерения, документа, публикации или пояснение способа оценки.
rotationEulerDeg|Начальная ориентация модели|°|Поворот визуальной модели вокруг X/Y/Z. Не меняет физические точки роторов, центр масс или инерцию.
confidence|Уверенность||Оценка доверия к источнику 0…1; не вероятность физической точности симулятора.
'''
help={}
for line in text.strip().splitlines():
 k,n,u,d=line.split('|',3);help[k]={'name':n,'unit':u,'description':d}
keys={k for d in defs.values() for k in d.get('properties',{})};missing=keys-help.keys()
assert not missing,missing
names={'Basic':'Базовая','Advanced':'Расширенная','AutoBox':'Коробка (оценка)','ManualPrincipal':'Главные моменты вручную','FirstOrder':'Первый порядок','RotorInertia':'Баланс моментов','OmegaSquared':'Ω² — коэффициенты','RpmTable':'RPM-таблица','CtCq':'Ct / Cq','PerformanceMap':'Карта RPM / J','Reject':'Запретить','Clamp':'Граничные значения','AxisApproximation':'По осям','ProjectedArea':'По проекции','Surfaces':'Поверхности','None':'Выключено','Simple':'Упрощённая','Electrical':'Электрическая','MeshDirectionalLUT':'Силуэты mesh (готовая LUT)','ManualDirectionalLUT':'Таблица направлений','Manufacturer':'Производитель','Measured':'Измерение','Calculated':'Вычисление','AutoGeometry':'Из геометрии','Preset':'Пресет','Estimated':'Оценка','User':'Пользователь','UnityLeftHandedYUpZForward':'X вправо · Y вверх · Z вперёд','ReportOnly':'Только диагностика'}
for k,n in names.items(): help[k]={'name':n,'unit':'','description':''}
examples={'$types':{}}
def walk(value,rule):
 if '$ref' in rule:
  name=rule['$ref'].split('/')[-1]; examples['$types'].setdefault(name,value);rule=defs[name]
 if rule['type']=='object':
  for k,v in value.items():
   if k in rule['properties']:
    examples.setdefault(k,v);walk(v,rule['properties'][k])
 elif rule['type']=='array':
  for v in value:walk(v,rule['items'])
for file in ['quad_test_thermal','quad_test_basic','quad_test_rpm_table','quad_test_performance_map','quad_test_surfaces','reference_crazyflie20']:
 walk(json.loads((r/f'Assets/DronePhysics/Resources/DronePhysics/{file}.json').read_text()),{'$ref':'#/$defs/DroneProfile'})
examples.update({'rotationEulerDeg':[0,0,0],'name':'Новый дрон','schemaVersion':'1.0.0','thrustAxisLocal':[0,1,0],'normalLocal':[0,1,0],'directionLocal':[1,0,0],'principalAxesRotationXyzw':[0,0,0,1],'sourceType':'User','source':'Ввод в конфигураторе','confidence':1,'modelScaleMetersPerUnit':1})
for k,v in {'EfficiencyPoint':{'loadFraction':0,'efficiency':0.85},'RotorOperatingEnvelopeProfile':{'model':'ReportOnly','maxAxialClimbSpeedMps':10,'maxAxialDescentSpeedMps':5,'maxLateralSpeedMps':20}}.items(): examples['$types'].setdefault(k,v)
for f,d in [('DroneParameters',help),('DroneParameterDefaults',examples)]: (r/f'Assets/DroneUI/Resources/DroneLab/{f}.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('Catalog:',len(keys),'physical field keys with help; defaults for',len(examples['$types']),'structures')
